function normalizar(texto) {
  return texto.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function coincidePalabra(a, b) {
  const min = Math.min(a.length, b.length);
  if (min < 3) return a === b;
  return a.startsWith(b) || b.startsWith(a);
}

function mejorCoincidencia(termino) {
  const palabras = normalizar(termino).split(/\s+/);
  let mejor = null;
  let mejorPuntos = 0;
  for (const prod of catalogo) {
    const nombreWords = normalizar(prod.name).split(/\s+/);
    const coincide = palabras.filter(w => nombreWords.some(nw => coincidePalabra(nw, w))).length;
    if (coincide === palabras.length && coincide > mejorPuntos) {
      mejorPuntos = coincide;
      mejor = prod;
    }
  }
  return mejor;
}

