const datos = JSON.parse(jsonLimpio);

return datos.productos.map(p => {
  const mejor = mejorCoincidencia(p.termino_busqueda);
  const numero = mejor ? parseInt(mejor.code.slice(2), 10) : null;
  const product_id = numero ? numero + 143 : null;

  return {
    ...p,
    product_id,
    producto_catalogo: mejor ? mejor.name : null,
    default_code: mejor ? mejor.code : null
  };
});

